insert into public.docs (path, doc, writer) values
  ('recaps/practice', '{"at":1789827389755,"body":{"headline":"Aspendos Opens Its Arms, Then Checks Its Watch","honours":[{"citation":"A two at the third and another at the seventh, the only player to manage the trick twice. Aspendos handed out those holes reluctantly and to nobody else.","slot":"shot_of_the_day","winner":"g6"},{"citation":"Net fifty-two, four clear of the next man, with twos at the second and the twelfth. A practice round played as though somebody were writing it down, which somebody was.","slot":"round_of_the_day","winner":"g2"},{"citation":"A seven at the fourteenth is the sort of number that follows a man home. Devin O answered it with four, four, three, five to the house, and gave the hole nothing further to work with.","slot":"best_recovery","winner":"g11"},{"citation":"The highest net total of the eight, signed and handed in without a single stroke of the triple-bogey cap for company. The card said what happened, which is all a card is asked to do.","slot":"honest_scorecard","winner":"g3"}],"narrative":["Aspendos on a Tuesday is a course with nothing at stake and every intention of being remembered anyway. Par 72, eighteen holes of practice that count for precisely nothing, and round zero of three that will. Four pairs went out at better ball, net to par, and four came back with numbers: Ray V and Drea at twenty-six under, the two Norbertos at twenty-four, Duncan W and DP at twenty, Matt D and Devin O at nineteen. A rehearsal, then, played rather firmly.","paragraphs","Individually the day belonged to Norberto Jr., whose net fifty-two included a two at the second and a two at the twelfth, and to Duncan W a stroke behind him at fifty-three. The side games were shared out with some tact: Norberto III nearest the flag at the seventh, DP longest at the third, and a solitary Bingo Bango Bongo point to Norberto Jr., which is the sort of haul that suggests the honours board was being polite. Ray V, meanwhile, posted a two at the third and another at the seventh.","The course, to its credit, never needed to raise its voice. The triple-bogey cap sat unused all afternoon, nought times invoked across eight cards, which on a practice day is the closest thing to a compliment a golfer receives. The only real movement came late, when the leading pair took two shots out of third place between the thirteenth and the fourteenth and the afternoon quietly settled. Nothing counted. Everybody, one suspects, counted anyway."],"pairNotes":{"p1":"Twenty-four under between them, and the Norberto surname now has a scoring average to live up to.","p2":"Nineteen under and fourth, which on this evidence is a placing rather than a verdict.","p3":"Twenty-six under and the best card of a day that officially does not exist.","p5":"Twenty under, built on two of the four lowest net rounds in the field."},"swing":{"caption":"The leaders took two shots out of third place between the thirteenth and the fourteenth, and the order of the day stopped arguing.","value":"2 shots"}},"by":null,"rev":1,"rid":"practice","status":"draft"}'::jsonb, 'migration')
  on conflict (path) do update set doc = excluded.doc, writer = excluded.writer;

-- anyone the factory seeded who is not on the real roster
delete from public.docs where path like 'people/%' and path not in ('people/g1', 'people/g10', 'people/g11', 'people/g2', 'people/g3', 'people/g6', 'people/g9', 'people/o1', 'people/o3', 'people/s1', 'people/s2', 'people/s3', 'people/s4', 'people/s5', 'people/s6');
delete from public.docs where path like 'pairs/%' and path not in ('pairs/p1', 'pairs/p2', 'pairs/p3', 'pairs/p5');

commit;

-- Did it work?
select split_part(path, '/', 1) as collection, count(*)
  from public.docs group by 1 order by 1;

-- Expect:
